    {id:"tc-10",chapterId:"ch-05",title:"Leverage Has Teeth",state:"Delta",cityKey:"warri",characters:["Praise","Toza","Craftore"],category:0,purpose:"See how leverage magnifies losses in a simulation and close risk before liquidation.",panels:[["THE WARNING","⚠️","Toza's leveraged position is moving against him."],["MARGIN SHRINKS","📉","Craftore lays out a leverage comparison while the player checks a simulated account."],["EXIT IN TIME","🧯","Toza closes the position and reviews the loss."]],dialogue:[{speaker:"Toza",text:"It only needs to bounce a little. I can hold."},{speaker:"Praise",text:"Hope isn't a margin plan."},{speaker:"Craftore",text:"I built this comparison so you can see how quickly risk grows."},{speaker:"PLAYER",text:"Let's compare the liquidation risk before deciding."}],learningObjectives:["Understand long and short positions, margin, leverage and liquidation","Recognize funding costs"],prerequisites:["tc-09"],objectives:[{id:"tc10-position",text:"Open a sandbox futures position",target:"futures-simulator"},{id:"tc10-leverage",text:"Compare leverage levels",target:"leverage-comparison"},{id:"tc10-margin",text:"Check margin and liquidation",target:"margin-panel"},{id:"tc10-close",text:"Close or reduce the position",target:"position-controls"}],success:{all:["tc10-position","tc10-leverage","tc10-margin","tc10-close"]},failure:{retryable:true,hint:"Reduce exposure before the simulated liquidation threshold is reached."},rewards:{xp:200,artifact:"leverage-risk-review",skills:["derivatives-basics"]},storyFlags:{set:["understands-leverage-risk"]},nextMission:"tc-11",cliffhanger:"A community has thousands of followers but almost no active members."},
    {id:"tc-11",chapterId:"ch-06",title:"A Community Is Not a Crowd",state:"Anambra",cityKey:"onitsha",characters:["Kodavic","Cybersage"],category:4,purpose:"Improve a quiet community by fixing onboarding instead of chasing empty follower counts.",panels:[["BIG NUMBERS, EMPTY ROOM","👥","A project has thousands of followers but few active users."],["ASK WHY","🗣️","Kodavic and Cybersage help the player interview new members."],["MAKE IT USEFUL","🧭","The team redesigns its first steps around a real user need."]],dialogue:[{speaker:"Kodavic",text:"The follower count keeps rising. Why does everyone leave?"},{speaker:"Cybersage",text:"Let's follow a newcomer through the first five minutes."},{speaker:"PLAYER",text:"I'll fix the confusing first step before suggesting another giveaway."}],learningObjectives:["Understand onboarding, engagement and retention","Measure meaningful participation"],prerequisites:["tc-10"],objectives:[{id:"tc11-onboard",text:"Inspect the welcome flow",target:"community-onboarding"},{id:"tc11-interview",text:"Talk to two members",target:"community-member",count:2},{id:"tc11-fix",text:"Build a clearer first step",target:"onboarding-editor"},{id:"tc11-measure",text:"Choose a useful retention metric",target:"community-metrics"}],success:{all:["tc11-onboard","tc11-interview","tc11-fix","tc11-measure"]},failure:{retryable:true,hint:"Choose a metric that reflects whether people actually get value."},rewards:{xp:180,artifact:"community-onboarding-plan",skills:["community-building"]},storyFlags:{set:["community-root-cause-found"]},nextMission:"tc-12",cliffhanger:"A fake administrator is sending malicious links to members."},
    {id:"tc-12",chapterId:"ch-06",title:"The Guardians of the Server",state:"Anambra",cityKey:"onitsha",characters:["Reina","Cclya"],category:4,purpose:"Contain an impersonation attempt, help a targeted member and calm a confused community.",panels:[["FAKE ADMIN","🚨","A new account impersonates an administrator and sends a malicious link."],["CONTAIN THE INCIDENT","🛡️","The player checks evidence, flags the account and supports a targeted member."],["RESTORE TRUST","📣","The moderators publish a clear, calm safety update."]],dialogue:[{speaker:"Reina",text:"Members are accusing each other. We need facts, fast."},{speaker:"Cclya",text:"And don't shame the person who clicked. Help them secure the account."},{speaker:"PLAYER",text:"I'll report the impersonator and post clear steps."}],learningObjectives:["Recognize impersonation and phishing","Practice moderation, de-escalation and incident escalation"],prerequisites:["tc-11"],objectives:[{id:"tc12-spot",text:"Identify the impersonator",target:"fake-admin"},{id:"tc12-help",text:"Help the targeted member",target:"member-safety"},{id:"tc12-calm",text:"De-escalate the dispute",target:"chat-moderation"},{id:"tc12-post",text:"Publish the safety notice",target:"announcement-board"}],success:{all:["tc12-spot","tc12-help","tc12-calm","tc12-post"]},failure:{retryable:true,hint:"Share verified safety steps and escalate evidence without exposing victims."},rewards:{xp:190,artifact:"incident-response-notice",skills:["moderation","scam-response"]},storyFlags:{set:["community-incident-contained"]},nextMission:"tc-13",cliffhanger:"An event poster carries the T3Kit symbol."},
    {id:"tc-13",chapterId:"ch-07",title:"You Have the Mic",state:"Enugu",cityKey:"enugu",characters:["Leemah","Kenny"],category:6,purpose:"Host a simulated live discussion by asking useful questions and managing speakers.",panels:[["THE HOST CANCELS","🎙️","The scheduled host disappears just before a Web3 live discussion."],["TAKE THE MIC","🗣️","The player organizes speakers, opens the room and handles a difficult question."],["THE POSTER","🧩","An old event poster bears the T3Kit symbol."]],dialogue:[{speaker:"Leemah",text:"The host cancelled. Can you keep this room useful?"},{speaker:"Kenny",text:"You don't need every answer. Ask a question worth hearing."},{speaker:"PLAYER",text:"I'll guide the conversation and verify claims."}],learningObjectives:["Practice hosting, speaker coordination and live moderation","Write a useful event recap"],prerequisites:["tc-12"],objectives:[{id:"tc13-research",text:"Review the event topic",target:"event-brief"},{id:"tc13-run",text:"Host the simulated discussion",target:"live-room"},{id:"tc13-question",text:"Handle a difficult question",target:"speaker-question"},{id:"tc13-recap",text:"Publish a concise recap",target:"event-recap"}],success:{all:["tc13-research","tc13-run","tc13-question","tc13-recap"]},failure:{retryable:true,hint:"Keep questions clear, give speakers room, and correct unsupported claims."},rewards:{xp:180,artifact:"event-recap",skills:["live-hosting","communication"]},storyFlags:{set:["hosted-first-space","found-t3kit-poster"]},nextMission:"tc-14",cliffhanger:"The project needs someone to explain its product clearly."},
    {id:"tc-14",chapterId:"ch-07",title:"Words That Open Doors",state:"Enugu",cityKey:"enugu",characters:["Kore","Veedima"],category:6,purpose:"Turn confusing product language into accurate beginner-friendly content.",panels:[["NOBODY GETS IT","📝","A useful product announcement is full of jargon and unsupported claims."],["MAKE IT CLEAR","✍️","The player checks the product facts, audience and core benefit."],["SHOW YOUR WORK","📲","Veedima asks the player to publish a clear educational post."]],dialogue:[{speaker:"Kore",text:"People read the announcement but still don't understand the product."},{speaker:"Veedima",text:"Plain words aren't less professional. They're more useful."},{speaker:"PLAYER",text:"I'll make the benefit clear and verify every claim."}],learningObjectives:["Practice technical communication, research and positioning"],prerequisites:["tc-13"],objectives:[{id:"tc14-research",text:"Inspect the product facts",target:"product-brief"},{id:"tc14-rewrite",text:"Rewrite the announcement",target:"content-editor"},{id:"tc14-post",text:"Create an educational post",target:"post-composer"},{id:"tc14-check",text:"Verify each claim",target:"claim-checker"}],success:{all:["tc14-research","tc14-rewrite","tc14-post","tc14-check"]},failure:{retryable:true,hint:"Remove promises you cannot prove and explain the product in plain language."},rewards:{xp:170,artifact:"verified-educational-post",skills:["content-writing","research"]},storyFlags:{set:["published-first-educational-post"]},nextMission:"tc-15",cliffhanger:"A contributor profile catches the attention of a small startup."},
    {id:"tc-15",chapterId:"ch-08",title:"The Profile That Opens Doors",state:"Plateau",cityKey:"jos",characters:["Web3_Esta","Love"],category:6,purpose:"Build a credible professional profile from real work and honest evidence.",panels:[["A PROFILE WITHOUT PROOF","🪪","The player's timeline is random, and the bio makes claims without examples."],["BUILD THE EVIDENCE","🧰","Web3_Esta helps organize skills, work samples and a portfolio."],["HONEST POSITIONING","🤝","Love: “Show what you can do and how you improve.”"]],dialogue:[{speaker:"Web3_Esta",text:"You don't need to pretend to be an expert."},{speaker:"Love",text:"Show the work, the learning and the progress."},{speaker:"PLAYER",text:"I'll build my profile around evidence."}],learningObjectives:["Practice personal positioning, portfolios and networking"],prerequisites:["tc-14"],objectives:[{id:"tc15-path",text:"Choose a professional direction",target:"career-path-picker"},{id:"tc15-bio",text:"Write a clear bio",target:"profile-editor"},{id:"tc15-work",text:"Add work samples",target:"portfolio-board"},{id:"tc15-audit",text:"Check claims against evidence",target:"profile-review"}],success:{all:["tc15-path","tc15-bio","tc15-work","tc15-audit"]},failure:{retryable:true,hint:"Keep every skill claim tied to a real sample or a clear learning goal."},rewards:{xp:180,artifact:"practitioner-profile-draft",skills:["personal-branding","portfolio-building"]},storyFlags:{set:["profile-created"]},nextMission:"tc-16",cliffhanger:"A startup has a small paid contributor task and asks the player to apply."},
    {id:"tc-16",chapterId:"ch-08",title:"The First Opportunity",state:"Plateau",cityKey:"jos",characters:["J.Jonathan","Essa"],category:8,purpose:"Apply for a realistic entry-level contribution using a practical work sample.",panels:[["A SMALL OPENING","📨","A startup needs research and user-feedback help, not a miracle worker."],["SHOW YOUR WORK","🧪","The player reviews requirements and completes a small sandbox task."],["FIRST STEP","📬","The application is sent with an honest work sample."]],dialogue:[{speaker:"J.Jonathan",text:"We need someone reliable who can investigate a user problem."},{speaker:"Essa",text:"A small task can be a real opportunity to learn."},{speaker:"PLAYER",text:"I'll show what I can do, not claim what I can't."}],learningObjectives:["Practice applications, work samples and feedback","Identify fraudulent job offers"],prerequisites:["tc-15"],objectives:[{id:"tc16-role",text:"Review role requirements",target:"job-description"},{id:"tc16-sample",text:"Complete a work sample",target:"contributor-task"},{id:"tc16-safety",text:"Check the offer for red flags",target:"job-offer-check"},{id:"tc16-apply",text:"Submit the application",target:"application-terminal"}],success:{all:["tc16-role","tc16-sample","tc16-safety","tc16-apply"]},failure:{retryable:true,hint:"Never pay an upfront fee to unlock a supposed job."},rewards:{xp:190,artifact:"first-contributor-application",skills:["professional-communication"]},storyFlags:{set:["first-opportunity-earned"]},nextMission:"tc-17",cliffhanger:"In Kano, a product team has built too many features."},
    {id:"tc-17",chapterId:"ch-09",title:"The Product People Need",state:"Kano",cityKey:"kano",characters:["White Coach","Abdul"],category:8,purpose:"Improve a product by mapping the user's real problem and testing a focused change.",panels:[["TOO MANY BUTTONS","📱","The startup's app has features everywhere, but users cannot finish the main task."],["FOLLOW THE USER","🧭","The player maps the journey and watches two simulated users."],["LESS, BUT BETTER","✨","The team removes clutter and tests a focused improvement."]],dialogue:[{speaker:"White Coach",text:"The roadmap is full. Why are users still stuck?"},{speaker:"Abdul",text:"Let's watch somebody try to finish one real task."},{speaker:"PLAYER",text:"I'll fix the biggest blocker first."}],learningObjectives:["Practice user research, prioritization and usability testing"],prerequisites:["tc-16"],objectives:[{id:"tc17-interview",text:"Interview two users",target:"product-user",count:2},{id:"tc17-map",text:"Map the user journey",target:"journey-board"},{id:"tc17-prioritize",text:"Choose the highest-impact fix",target:"priority-board"},{id:"tc17-test",text:"Test the revised flow",target:"usability-test"}],success:{all:["tc17-interview","tc17-map","tc17-prioritize","tc17-test"]},failure:{retryable:true,hint:"Choose the fix that helps users finish their main job."},rewards:{xp:180,artifact:"product-improvement-brief",skills:["product-management","ux-thinking"]},storyFlags:{set:["product-flow-improved"]},nextMission:"tc-18",cliffhanger:"A growth proposal promises thousands of users for an upfront payment."},
    {id:"tc-18",chapterId:"ch-09",title:"The Growth Experiment",state:"Kano",cityKey:"kano",characters:["David","Kanyin"],category:5,purpose:"Design a small measurable growth experiment and reject fake engagement promises.",panels:[["A BIG PROMISE","📈","A vendor offers thousands of users if the startup pays first."],["TEST THE IDEA","🧪","David asks the player to define an audience, hypothesis and useful metric."],["THE RED FLAG","🚩","Kanyin spots the suspicious upfront offer."]],dialogue:[{speaker:"David",text:"Before we spend, what user behaviour are we trying to change?"},{speaker:"Kanyin",text:"This vendor promises numbers but shows no evidence."},{speaker:"PLAYER",text:"Let's test a small honest campaign first."}],learningObjectives:["Practice growth experiments, funnels and meaningful metrics","Recognize fake engagement schemes"],prerequisites:["tc-17"],objectives:[{id:"tc18-audience",text:"Define the target audience",target:"audience-board"},{id:"tc18-test",text:"Build a small campaign experiment",target:"campaign-builder"},{id:"tc18-metric",text:"Choose a meaningful metric",target:"growth-dashboard"},{id:"tc18-vendor",text:"Review the suspicious proposal",target:"vendor-proposal"}],success:{all:["tc18-audience","tc18-test","tc18-metric","tc18-vendor"]},failure:{retryable:true,hint:"Ask how users are acquired and how the result can be verified."},rewards:{xp:180,artifact:"growth-experiment-brief",skills:["growth-strategy","analytics"]},storyFlags:{set:["fake-growth-offer-rejected"]},nextMission:"tc-19",cliffhanger:"An Edo startup must choose between several funding offers."},
    {id:"tc-19",chapterId:"ch-10",title:"The Funding Decision",state:"Edo",cityKey:"benin",characters:["Mcbond","Alpha.RWA"],category:5,purpose:"Compare fictional funding proposals and identify token allocation and governance conflicts.",panels:[["RUNWAY RUNNING OUT","💼","A startup needs funding to keep its product alive."],["COMPARE THE TERMS","📄","The player reviews grants, venture capital and token-based offers."],["THE TRADE-OFF","⚖️","The team chooses a fit-for-purpose option with transparent obligations."]],dialogue:[{speaker:"Mcbond",text:"We need runway, but I don't want to sign away the project."},{speaker:"Alpha.RWA",text:"Read the allocation, vesting and control terms before the headline number."},{speaker:"PLAYER",text:"I'll compare obligations as well as cash."}],learningObjectives:["Understand grants, venture capital, token allocation and vesting"],prerequisites:["tc-18"],objectives:[{id:"tc19-budget",text:"Review the startup budget",target:"startup-budget"},{id:"tc19-offers",text:"Compare three fictional offers",target:"funding-proposal",count:3},{id:"tc19-conflict",text:"Identify conflicts of interest",target:"term-sheet-review"},{id:"tc19-recommend",text:"Recommend a funding route",target:"founder-table"}],success:{all:["tc19-budget","tc19-offers","tc19-conflict","tc19-recommend"]},failure:{retryable:true,hint:"Consider control, obligations, time horizon and long-term sustainability."},rewards:{xp:190,artifact:"funding-comparison",skills:["startup-finance","token-economics"]},storyFlags:{set:["funding-tradeoffs-understood"]},nextMission:"tc-20",cliffhanger:"A tokenized property project cannot prove the rights behind its claims."},
    {id:"tc-20",chapterId:"ch-10",title:"The Asset That Exists on Paper",state:"Edo",cityKey:"benin",characters:["BigWealth","BigSam"],category:5,purpose:"Investigate tokenized real-world asset claims and flag missing legal and custody evidence.",panels:[["OWNERSHIP CLAIM","🏠📄","A project says a token represents property, but its documents are incomplete."],["ASK WHAT IT MEANS","🔍","The player checks ownership, custody, redemption and legal rights."],["PAUSE THE PROMO","⏸️","The team delays its announcement until the claims can be supported."]],dialogue:[{speaker:"BigWealth",text:"The token is live. Does that prove the property claim?"},{speaker:"BigSam",text:"Not without evidence for the asset and the rights it represents."},{speaker:"PLAYER",text:"I'll list what's missing before this is promoted."}],learningObjectives:["Understand tokenized assets, custody, redemption and verification"],prerequisites:["tc-19"],objectives:[{id:"tc20-docs",text:"Review the fictional asset documents",target:"asset-documents"},{id:"tc20-rights",text:"Identify missing rights evidence",target:"rights-check"},{id:"tc20-custody",text:"Inspect custody and redemption",target:"custody-panel"},{id:"tc20-report",text:"Submit a due-diligence note",target:"due-diligence-desk"}],success:{all:["tc20-docs","tc20-rights","tc20-custody","tc20-report"]},failure:{retryable:true,hint:"A token cannot by itself prove that an underlying asset claim is legitimate."},rewards:{xp:190,artifact:"asset-due-diligence-note",skills:["rwa-research"]},storyFlags:{set:["rwa-claims-reviewed"]},nextMission:"tc-21",cliffhanger:"A confident AI report about blockchain activity contains false information."},
    {id:"tc-21",chapterId:"ch-11",title:"The Machine That Thinks",state:"Cross River",cityKey:"uyo",characters:["Blessing","Odion"],category:8,purpose:"Verify a fictional AI-generated on-chain report against source data and improve its instructions.",panels:[["CONFIDENT, WRONG","🤖❌","An AI tool gives a polished report with an incorrect wallet attribution."],["CHECK THE SOURCE","🔎","The player compares claims with simulated transaction records."],["FIX THE WORKFLOW","🧠","The team adds source checks and human review for important decisions."]],dialogue:[{speaker:"Blessing",text:"The report sounds certain. One of its claims is wrong."},{speaker:"Odion",text:"Let's find the source data before changing the prompt."},{speaker:"PLAYER",text:"I'll verify the facts, then retest it."}],learningObjectives:["Understand AI limits, on-chain analysis and human verification"],prerequisites:["tc-20"],objectives:[{id:"tc21-report",text:"Inspect the generated report",target:"ai-report"},{id:"tc21-verify",text:"Verify claims against source records",target:"source-ledger"},{id:"tc21-fix",text:"Improve the analysis instructions",target:"prompt-workbench"},{id:"tc21-retest",text:"Retest the output",target:"ai-report-test"}],success:{all:["tc21-report","tc21-verify","tc21-fix","tc21-retest"]},failure:{retryable:true,hint:"Trace every important claim to a source; confidence is not evidence."},rewards:{xp:190,artifact:"verified-ai-analysis",skills:["ai-verification","onchain-research"]},storyFlags:{set:["ai-report-corrected"]},nextMission:"tc-22",cliffhanger:"A cross-chain route leads to another T3Kit archive fragment."},
    {id:"tc-22",chapterId:"ch-11",title:"Beyond One Blockchain",state:"Cross River",cityKey:"uyo",characters:["Princess","Racheal"],category:2,purpose:"Trace a sandbox cross-chain transfer and identify bridge dependencies and phishing risks.",panels:[["TWO NETWORKS","🌉","A dApp needs to move a test asset between two simulated networks."],["TRACE THE ROUTE","🧭","The player follows the bridge status and network fees."],["THE LOOKALIKE","🚨","A fake bridge interface asks for a dangerous approval."]],dialogue:[{speaker:"Princess",text:"The transfer is stuck between networks. Can you trace it?"},{speaker:"Racheal",text:"Use the official route and inspect every approval."},{speaker:"PLAYER",text:"I'll verify the bridge and the destination before continuing."}],learningObjectives:["Understand layer-one/layer-two networks, bridges, fees and cross-chain risks"],prerequisites:["tc-21"],objectives:[{id:"tc22-networks",text:"Compare two sandbox networks",target:"network-comparison",count:2},{id:"tc22-trace",text:"Trace the cross-chain transfer",target:"bridge-tracker"},{id:"tc22-fake",text:"Reject the fake bridge",target:"bridge-lookalike"},{id:"tc22-explain",text:"Explain the added dependency",target:"racheal-npc"}],success:{all:["tc22-networks","tc22-trace","tc22-fake","tc22-explain"]},failure:{retryable:true,hint:"Verify the official route and remember that bridges add security dependencies."},rewards:{xp:190,artifact:"cross-chain-risk-map",skills:["interoperability"]},storyFlags:{set:["bridge-risk-understood","t3kit-cross-chain-clue"]},nextMission:"tc-23",cliffhanger:"A treasury vote may explain why the T3Kit archive was abandoned."},
    {id:"tc-23",chapterId:"ch-12",title:"The Vote That Changed Everything",state:"Bauchi",cityKey:"bauchi",characters:["Seun","Dorcas"],category:4,purpose:"Review fictional DAO proposals and discover a neglected treasury behind the vote.",panels:[["TWO PROPOSALS","🗳️","A DAO must choose between two competing treasury proposals."],["FOLLOW THE MONEY","📊","The player compares budgets, risks, participation and treasury history."],["THE EMPTY ROOM","🏛️","The vote reveals that members have been inactive for months."]],dialogue:[{speaker:"Seun",text:"Both proposals sound convincing. What are we missing?"},{speaker:"Dorcas",text:"Check the treasury and who is actually participating."},{speaker:"PLAYER",text:"I'll compare the evidence before casting a sandbox vote."}],learningObjectives:["Understand DAOs, proposals, voting and treasury management"],prerequisites:["tc-22"],objectives:[{id:"tc23-proposals",text:"Review both proposals",target:"dao-proposal",count:2},{id:"tc23-treasury",text:"Inspect the simulated treasury",target:"dao-treasury"},{id:"tc23-vote",text:"Cast a sandbox vote",target:"dao-voting"},{id:"tc23-response",text:"Recommend a response to inactivity",target:"dao-forum"}],success:{all:["tc23-proposals","tc23-treasury","tc23-vote","tc23-response"]},failure:{retryable:true,hint:"A governance decision needs context, evidence and a look at who is participating."},rewards:{xp:190,artifact:"dao-vote-record",skills:["dao-governance"]},storyFlags:{set:["dao-inactivity-discovered"]},nextMission:"tc-24",cliffhanger:"A security report reveals a vulnerability nobody wanted to hear about."},
    {id:"tc-24",chapterId:"ch-12",title:"The Audit Nobody Wanted",state:"Bauchi",cityKey:"bauchi",characters:["Joe","Mike"],category:8,purpose:"Prioritize a simulated vulnerability, plan responsible disclosure and verify a test fix.",panels:[["BEFORE LAUNCH","🛑","A serious vulnerability is reported shortly before launch."],["PROVE THE IMPACT","🧪","The player reviews the safe reproduction and ranks severity."],["FIX, THEN VERIFY","🔐","The team delays launch and confirms the patch in a test environment."]],dialogue:[{speaker:"Joe",text:"The report is serious. We need to know what it affects."},{speaker:"Mike",text:"Momentum can recover. Lost trust is harder."},{speaker:"PLAYER",text:"I'll reproduce it safely and verify the fix."}],learningObjectives:["Practice threat modeling, remediation, testing and responsible disclosure"],prerequisites:["tc-23"],objectives:[{id:"tc24-report",text:"Inspect the vulnerability report",target:"security-report"},{id:"tc24-impact",text:"Rank severity and impact",target:"severity-board"},{id:"tc24-disclose",text:"Prepare a responsible disclosure note",target:"disclosure-desk"},{id:"tc24-test",text:"Verify the test fix",target:"security-regression"}],success:{all:["tc24-report","tc24-impact","tc24-disclose","tc24-test"]},failure:{retryable:true,hint:"Keep reproduction inside the sandbox and verify the fix before launch."},rewards:{xp:200,artifact:"security-remediation-report",skills:["security-fundamentals"]},storyFlags:{set:["security-pattern-confirmed"]},nextMission:"tc-25",cliffhanger:"An artist's collection raises a dispute about what an NFT actually grants."},
    {id:"tc-25",chapterId:"ch-13",title:"Ownership Is Not a Screenshot",state:"Abia",cityKey:"aba",characters:["Gbemi","FemiY"],category:7,purpose:"Clarify NFT provenance, licensing and the difference between a token and copyright.",panels:[["WHO OWNS WHAT?","🎨","Creators disagree about whether minting an NFT transfers copyright."],["READ THE TERMS","📜","The player inspects creator identity, licensing and actual holder rights."],["CLEAR THE PROMISE","🖼️","The collection documentation is updated before launch."]],dialogue:[{speaker:"Gbemi",text:"A buyer says owning the token means they own my copyright."},{speaker:"FemiY",text:"Let's check what the licence actually grants."},{speaker:"PLAYER",text:"I'll make the rights clear before anyone buys."}],learningObjectives:["Understand NFTs, provenance, licensing and creator monetization"],prerequisites:["tc-24"],objectives:[{id:"tc25-item",text:"Inspect the fictional collectible",target:"nft-collectible"},{id:"tc25-terms",text:"Review its licence",target:"nft-license"},{id:"tc25-rights",text:"Identify the actual holder rights",target:"rights-summary"},{id:"tc25-docs",text:"Update the collection description",target:"nft-listing-editor"}],success:{all:["tc25-item","tc25-terms","tc25-rights","tc25-docs"]},failure:{retryable:true,hint:"A token and copyright are different rights; read the licence."},rewards:{xp:180,artifact:"clear-nft-license-summary",skills:["digital-ownership"]},storyFlags:{set:["nft-rights-clarified"]},nextMission:"tc-26",cliffhanger:"The player reunites with Softstorm and IamAbdul to inspect an abandoned repository."},
    {id:"tc-26",chapterId:"ch-14",title:"The Open-Source Promise",state:"Niger",cityKey:"minna",characters:["Softstorm","IamAbdul"],category:8,purpose:"Make a small, reviewable contribution to an abandoned project and find the earliest T3Kit design note.",panels:[["THE OLD REPOSITORY","🗂️","The code is public, but its documentation is incomplete and contributors have disappeared."],["MAKE ONE USEFUL CHANGE","🛠️","The player improves a short guide and prepares a contribution note."],["THE DESIGN NOTE","🧩","A commit contains an early T3Kit document about people contributing different skills."]],dialogue:[{speaker:"IamAbdul",text:"Omo, the project is still here, but nobody knows how to run it."},{speaker:"Softstorm",text:"Start small. Make it easier for the next person."},{speaker:"PLAYER",text:"I'll document the setup and explain what changed."}],learningObjectives:["Understand repositories, version control, issues, pull requests and maintenance"],prerequisites:["tc-25"],objectives:[{id:"tc26-repo",text:"Explore the repository",target:"open-source-repo"},{id:"tc26-issue",text:"Choose an unresolved issue",target:"repo-issue"},{id:"tc26-docs",text:"Improve a setup guide",target:"documentation-editor"},{id:"tc26-pr",text:"Submit a contribution proposal",target:"pull-request-sandbox"}],success:{all:["tc26-repo","tc26-issue","tc26-docs","tc26-pr"]},failure:{retryable:true,hint:"Keep the change small, explain it clearly and make it easy to review."},rewards:{xp:200,artifact:"first-open-source-contribution",skills:["open-source-collaboration"]},storyFlags:{set:["t3kit-origin-document-found"]},nextMission:"tc-27",cliffhanger:"The archive says T3Kit was designed as an ecosystem, not a single product."},
    {id:"tc-27",chapterId:"ch-14",title:"The Economy of Trust",state:"Niger",cityKey:"minna",characters:["Joe_Sef","Larai"],category:6,purpose:"Connect evidence from earlier chapters and reconstruct why T3Kit brought different professional roles together.",panels:[["BACK TO THE WORKSPACE","🗃️","Joe_Sef and Larai lay out records gathered across the journey."],["CONNECT THE CLUES","🧩","The player links the ledger, security incident, event poster and repository note."],["THE MISSING SENTENCE","✨","The archive reveals the route to KitCity."]],dialogue:[{speaker:"Joe_Sef",text:"You have the pieces. What do they say together?"},{speaker:"Larai",text:"Look for what repeats across the different projects."},{speaker:"PLAYER",text:"T3Kit connects people who learn, build, share and contribute."}],learningObjectives:["Connect ecosystem roles and evaluate evidence across sources"],prerequisites:["tc-26"],objectives:[{id:"tc27-evidence",text:"Review collected story artifacts",target:"journey-journal"},{id:"tc27-links",text:"Connect four clues",target:"clue-board",count:4},{id:"tc27-check",text:"Resolve an archive contradiction",target:"archive-review"},{id:"tc27-submit",text:"Submit the reconstruction",target:"archive-terminal"}],success:{all:["tc27-evidence","tc27-links","tc27-check","tc27-submit"]},failure:{retryable:true,hint:"Use evidence from multiple chapters; don't assume one clue explains everything."},rewards:{xp:220,artifact:"t3kit-archive-reconstruction",skills:["ecosystem-thinking"]},storyFlags:{set:["t3kit-purpose-understood","kitcity-destination-unlocked"]},nextMission:"tc-28",cliffhanger:"The final map points toward Kogi — and a city that does not appear on ordinary maps."},
    {id:"tc-28",chapterId:"ch-15",title:"Every Piece Matters",state:"Kogi",cityKey:"lokoja",characters:["Unique","Christol","Craftore"],category:8,purpose:"Combine product, user, technical and community thinking to solve one final ecosystem problem.",panels:[["THE FINAL ROUTE","🗺️","Unique and Christol lay out the map to KitCity."],["ONE SHARED PROBLEM","🧩","A simulated team faces a product issue involving users, technology and trust."],["READY TO ARRIVE","🚆","The player solves the issue by coordinating different skills."]],dialogue:[{speaker:"Unique",text:"You know the pieces now. Can you put them to work together?"},{speaker:"Christol",text:"Don't reach for the fanciest tool. Start with the real problem."},{speaker:"Craftore",text:"The route is open. KitCity is next."}],learningObjectives:["Combine research, product, technology and communication skills"],prerequisites:["tc-27"],objectives:[{id:"tc28-problem",text:"Identify the root problem",target:"ecosystem-case"},{id:"tc28-team",text:"Assign skills to a simulated team",target:"team-board"},{id:"tc28-solution",text:"Build and test a solution",target:"ecosystem-workbench"},{id:"tc28-present",text:"Present the result",target:"team-presentation"}],success:{all:["tc28-problem","tc28-team","tc28-solution","tc28-present"]},failure:{retryable:true,hint:"Combine the right roles and show evidence that the solution works."},rewards:{xp:250,artifact:"ecosystem-capstone",skills:["cross-functional-practice"]},storyFlags:{set:["final-map-earned"]},nextMission:"tc-29",cliffhanger:"The gates of KitCity appear beyond the ridge."},
    {id:"tc-29",chapterId:"ch-final",title:"The Gatekeeper",state:"KitCity",cityKey:"kitcity",characters:["Softstorm","White Coach","Craftore"],category:8,purpose:"Arrive in KitCity, meet practitioners and select a specialization for the final practical assessment.",panels:[["THE CITY","🌇","A future-facing Nigerian city hums with builders, researchers, traders, creators and communities."],["THE QUESTION","🚪","PLAYER: “Why did everything keep leading back to T3Kit?” Softstorm: “It connects people, products and opportunities.”"],["THE GATE OPENS","✨","The player chooses a path and registers for a practical assessment."]],dialogue:[{speaker:"PLAYER",text:"So this is KitCity."},{speaker:"Softstorm",text:"You've come a long way."},{speaker:"PLAYER",text:"Why did everything lead back to T3Kit?"},{speaker:"Softstorm",text:"Because no one skill builds an ecosystem alone."}],learningObjectives:["Recognize how professional roles interact across the ecosystem"],prerequisites:["tc-28"],objectives:[{id:"tc29-explore",text:"Explore the central district",target:"kitcity-central"},{id:"tc29-meet",text:"Meet three professional representatives",target:"kitcity-practitioner",count:3},{id:"tc29-path",text:"Choose a specialization",target:"specialization-picker"},{id:"tc29-register",text:"Register for the assessment",target:"assessment-desk"}],success:{all:["tc29-explore","tc29-meet","tc29-path","tc29-register"]},failure:{retryable:true,hint:"Explore the district and speak to practitioners before choosing a path."},rewards:{xp:200,artifact:"kitcity-practitioner-registration",skills:["specialization-selected"]},storyFlags:{set:["arrived-kitcity","specialization-registered"]},nextMission:"tc-30",cliffhanger:"The gatekeeper opens the assessment room."},
    {id:"tc-30",chapterId:"ch-final",title:"Prove Yourself",state:"KitCity",cityKey:"kitcity",characters:["White Coach","Craftore"],category:8,purpose:"Complete a retryable, sandboxed practical assessment tailored to the player's chosen specialization.",panels:[["YOUR PATH","🧰","The assessment changes to match the specialization the player selected."],["DO THE WORK","🛠️","The player solves a safe, simulated challenge and records evidence."],["FEEDBACK","📋","The game explains strengths and next steps; the player can retry."]],dialogue:[{speaker:"White Coach",text:"We won't test every profession. Show us the path you chose."},{speaker:"Craftore",text:"Do the work, explain the decision and show the evidence."}],learningObjectives:["Demonstrate practical execution, judgment, safety and communication in one specialization"],prerequisites:["tc-29"],objectives:[{id:"tc30-challenge",text:"Complete the chosen practical challenge",target:"specialization-assessment"},{id:"tc30-evidence",text:"Submit supporting evidence",target:"assessment-evidence"},{id:"tc30-review",text:"Review feedback and retry if needed",target:"assessment-review"}],success:{all:["tc30-challenge","tc30-evidence","tc30-review"],rubric:["understanding","execution","problem-solving","security","communication","collaboration"]},failure:{retryable:true,hint:"Use the feedback to improve your work, then try again."},rewards:{xp:300,artifact:"kitcity-practitioner-profile",skills:["assessed-specialization"]},storyFlags:{set:["assessment-passed"]},nextMission:"tc-31",cliffhanger:"The original mentors have gathered in the central hall."},
    {id:"tc-31",chapterId:"ch-final",title:"The Reveal",state:"KitCity",cityKey:"kitcity",characters:["Softstorm","IamAbdul","Joe_Sef","Larai","Unique","Christol"],category:6,purpose:"Resolve the T3Kit mystery, recognize the player's growth and open the post-story world.",panels:[["EVERYONE RETURNS","🎉","Familiar faces gather in KitCity's central hall."],["THE QUESTION","💬","Softstorm asks what Web3 means to the player now."],["THE ANSWER","🌅","The player chooses what they want to build, contribute or explore next."]],dialogue:[{speaker:"Softstorm",text:"When you started, what did you think Web3 was?"},{speaker:"PLAYER",choices:["A way to make money.","A complicated technology.","An opportunity I didn't understand."]},{speaker:"Softstorm",text:"And now?"},{speaker:"PLAYER",choices:["A world I can build in.","An ecosystem I can contribute to.","A career path I can pursue.","A space I want to keep exploring."]},{speaker:"Softstorm",text:"The point was never to memorize everything. Learn how to find answers, work with people and contribute something useful."}],learningObjectives:["Reflect on learning and choose a post-story direction"],prerequisites:["tc-30"],objectives:[{id:"tc31-reflect",text:"Reflect on the journey",target:"reflection-dialogue"},{id:"tc31-choose",text:"Choose the next direction",target:"epilogue-choice"},{id:"tc31-journal",text:"Review the journey journal and artifacts",target:"journey-journal"}],success:{all:["tc31-reflect","tc31-choose","tc31-journal"]},failure:{retryable:true,hint:"The ending is about your journey; choose the response that best reflects what you learned."},rewards:{xp:400,artifact:"kitcity-web3-practitioner-profile",skills:["journey-complete"]},storyFlags:{set:["t3kit-mystery-resolved","main-story-complete","post-story-unlocked"]},nextMission:null,cliffhanger:"A new message appears: “We've got something new to build.”"}
